/* ================================================================== * 월 정산 리포트 (레거시) - 채널/등급/카테고리/월별 매출 · 결제 · 반품 · 배송 * 2009 최초 작성, 2014 채널 추가, 2018 쿠폰/반품 반영, 2021 B2B 추가 * 주의: 결제는 LEGACY 스키마 테이블 사용, 취소(99) 주문은 제외 * ================================================================== */ WITH ORD_BASE AS ( /* 기준 주문: 기간/상태/채널 조건은 화면에서 동적으로 들어온다 */ SELECT O.ORDER_ID, O.CUSTOMER_ID, O.ORDERED_AT, O.STATUS, O.TOTAL_AMOUNT, O.CHANNEL_CODE, O.SALES_REP_ID, TO_CHAR(O.ORDERED_AT, 'YYYYMM') AS ORD_YM, C.CUSTOMER_NAME AS CUST_NAME, C.REGION_CODE AS CUST_RGN, NVL(C.GRADE_CODE, 'BASIC') AS CUST_GRD FROM ORDERS O INNER JOIN CUSTOMER C ON C.CUSTOMER_ID = O.CUSTOMER_ID WHERE O.STATUS <> '99' AND C.IS_ACTIVE = 'Y'
O.CHANNEL_CODE IN #chnlList[]#
C.REGION_CODE = #rgnCd#
O.CHANNEL_CODE <> 'B2B'
), ITEM_AGG AS ( /* 주문별 상품 금액/수량 */ SELECT D.ORDER_ID, SUM(D.QUANTITY * D.UNIT_PRICE) AS ITEM_AMT, SUM(D.QUANTITY) AS ITEM_QTY, COUNT(*) AS ITEM_LINES, COUNT(DISTINCT D.PRODUCT_ID) AS PRD_KINDS FROM ORDER_ITEM D WHERE EXISTS (SELECT 1 FROM ORD_BASE B WHERE B.ORDER_ID = D.ORDER_ID) GROUP BY D.ORDER_ID ), PAY_AGG AS ( /* 결제: 레거시 스키마, 결제수단별 분리 */ SELECT P.ORDER_ID, SUM(P.AMOUNT) AS PAY_SUM, SUM(CASE WHEN P.METHOD_CODE = 'CARD' THEN P.AMOUNT ELSE 0 END) AS CARD_SUM, SUM(CASE WHEN P.METHOD_CODE = 'BANK' THEN P.AMOUNT ELSE 0 END) AS BANK_SUM, SUM(CASE WHEN P.METHOD_CODE = 'POINT' THEN P.AMOUNT ELSE 0 END) AS POINT_SUM, MAX(P.PAID_AT) AS LAST_PAY_DT FROM BILLING.PAYMENT P WHERE P.ORDER_ID IN (SELECT B.ORDER_ID FROM ORD_BASE B) GROUP BY P.ORDER_ID ), DLV_LAST AS ( /* 주문별 최종 배송 1건 (ROW_NUMBER) */ SELECT X.ORDER_ID, X.DELIVERY_STATUS, X.DELIVERED_AT, X.PROMISED_AT, X.CARRIER_CODE FROM ( SELECT V.ORDER_ID, V.DELIVERY_STATUS, V.DELIVERED_AT, V.PROMISED_AT, V.CARRIER_CODE, ROW_NUMBER() OVER (PARTITION BY V.ORDER_ID ORDER BY V.DELIVERED_AT DESC, V.DELIVERY_ID DESC) AS RN FROM DELIVERY V WHERE V.DELIVERY_STATUS <> 'CANCEL' ) X WHERE X.RN = 1 ), RTN_AGG AS ( SELECT R.ORDER_ID, SUM(R.RETURN_AMOUNT) AS RTN_SUM, COUNT(*) AS RTN_CNT, MAX(CASE WHEN R.REASON_CODE = 'DEFECT' THEN 1 ELSE 0 END) AS HAS_DEFECT FROM RETURN_ORDER R GROUP BY R.ORDER_ID ), CPN_AGG AS ( SELECT U.ORDER_ID, SUM(U.DISCOUNT_AMOUNT) AS DC_SUM, COUNT(DISTINCT U.COUPON_ID) AS CPN_CNT FROM COUPON_USAGE U GROUP BY U.ORDER_ID ), EMP_DEPT AS ( /* 영업사원 -> 부서 -> 상위부서 */ SELECT E.EMPLOYEE_ID, E.EMPLOYEE_NAME, DP.DEPARTMENT_NAME, UP.DEPARTMENT_NAME AS UPPER_DEPT_NM FROM EMPLOYEE E LEFT JOIN DEPARTMENT DP ON DP.DEPARTMENT_ID = E.DEPARTMENT_ID LEFT JOIN DEPARTMENT UP ON UP.DEPARTMENT_ID = DP.PARENT_DEPARTMENT_ID ), CTG_SALES AS ( /* 대분류 카테고리별 매출 */ SELECT D.ORDER_ID, NVL(PC.CATEGORY_NAME, CT.CATEGORY_NAME) AS TOP_CTG_NM, SUM(D.QUANTITY * D.UNIT_PRICE) AS CTG_AMT FROM ORDER_ITEM D INNER JOIN PRODUCT PR ON PR.PRODUCT_ID = D.PRODUCT_ID INNER JOIN CATEGORY CT ON CT.CATEGORY_ID = PR.CATEGORY_ID LEFT JOIN CATEGORY PC ON PC.CATEGORY_ID = CT.PARENT_CATEGORY_ID WHERE PR.IS_SELLABLE = 'Y' GROUP BY D.ORDER_ID, NVL(PC.CATEGORY_NAME, CT.CATEGORY_NAME) ), R_SEOUL AS ( /* 서울 권역 */ SELECT B.CUSTOMER_ID, SUM(CASE WHEN B.CUST_GRD = 'VVIP' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS VVIP_AMT, SUM(CASE WHEN B.CUST_GRD = 'VIP' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS VIP_AMT, SUM(CASE WHEN B.CUST_GRD = 'GOLD' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS GOLD_AMT, SUM(CASE WHEN B.CUST_GRD = 'SILVER' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS SILVER_AMT, SUM(CASE WHEN B.CUST_GRD = 'BASIC' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS BASIC_AMT, SUM(CASE WHEN B.CHANNEL_CODE = 'WEB' THEN B.TOTAL_AMOUNT ELSE 0 END) AS WEB_AMT, SUM(CASE WHEN B.CHANNEL_CODE = 'APP' THEN B.TOTAL_AMOUNT ELSE 0 END) AS APP_AMT, SUM(CASE WHEN B.CHANNEL_CODE = 'CALL' THEN B.TOTAL_AMOUNT ELSE 0 END) AS CALL_AMT, SUM(CASE WHEN B.CHANNEL_CODE = 'STORE' THEN B.TOTAL_AMOUNT ELSE 0 END) AS STORE_AMT, SUM(CASE WHEN B.CHANNEL_CODE = 'B2B' THEN B.TOTAL_AMOUNT ELSE 0 END) AS B2B_AMT, SUM(CASE WHEN DL.DELIVERED_AT > DL.PROMISED_AT THEN 1 ELSE 0 END) AS LATE_CNT, COUNT(DISTINCT B.ORDER_ID) AS ORD_CNT FROM ORD_BASE B LEFT JOIN ITEM_AGG I ON I.ORDER_ID = B.ORDER_ID LEFT JOIN DLV_LAST DL ON DL.ORDER_ID = B.ORDER_ID WHERE B.CUST_RGN = 'SEOUL' GROUP BY B.CUSTOMER_ID ), R_BUSAN AS ( /* 부산 권역 */ SELECT B.CUSTOMER_ID, SUM(CASE WHEN B.CUST_GRD = 'VVIP' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS VVIP_AMT, SUM(CASE WHEN B.CUST_GRD = 'VIP' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS VIP_AMT, SUM(CASE WHEN B.CUST_GRD = 'GOLD' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS GOLD_AMT, SUM(CASE WHEN B.CUST_GRD = 'SILVER' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS SILVER_AMT, SUM(CASE WHEN B.CUST_GRD = 'BASIC' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS BASIC_AMT, SUM(CASE WHEN B.CHANNEL_CODE = 'WEB' THEN B.TOTAL_AMOUNT ELSE 0 END) AS WEB_AMT, SUM(CASE WHEN B.CHANNEL_CODE = 'APP' THEN B.TOTAL_AMOUNT ELSE 0 END) AS APP_AMT, SUM(CASE WHEN B.CHANNEL_CODE = 'CALL' THEN B.TOTAL_AMOUNT ELSE 0 END) AS CALL_AMT, SUM(CASE WHEN B.CHANNEL_CODE = 'STORE' THEN B.TOTAL_AMOUNT ELSE 0 END) AS STORE_AMT, SUM(CASE WHEN B.CHANNEL_CODE = 'B2B' THEN B.TOTAL_AMOUNT ELSE 0 END) AS B2B_AMT, SUM(CASE WHEN DL.DELIVERED_AT > DL.PROMISED_AT THEN 1 ELSE 0 END) AS LATE_CNT, COUNT(DISTINCT B.ORDER_ID) AS ORD_CNT FROM ORD_BASE B LEFT JOIN ITEM_AGG I ON I.ORDER_ID = B.ORDER_ID LEFT JOIN DLV_LAST DL ON DL.ORDER_ID = B.ORDER_ID WHERE B.CUST_RGN = 'BUSAN' GROUP BY B.CUSTOMER_ID ), R_DAEGU AS ( /* 대구 권역 */ SELECT B.CUSTOMER_ID, SUM(CASE WHEN B.CUST_GRD = 'VVIP' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS VVIP_AMT, SUM(CASE WHEN B.CUST_GRD = 'VIP' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS VIP_AMT, SUM(CASE WHEN B.CUST_GRD = 'GOLD' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS GOLD_AMT, SUM(CASE WHEN B.CUST_GRD = 'SILVER' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS SILVER_AMT, SUM(CASE WHEN B.CUST_GRD = 'BASIC' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS BASIC_AMT, SUM(CASE WHEN B.CHANNEL_CODE = 'WEB' THEN B.TOTAL_AMOUNT ELSE 0 END) AS WEB_AMT, SUM(CASE WHEN B.CHANNEL_CODE = 'APP' THEN B.TOTAL_AMOUNT ELSE 0 END) AS APP_AMT, SUM(CASE WHEN B.CHANNEL_CODE = 'CALL' THEN B.TOTAL_AMOUNT ELSE 0 END) AS CALL_AMT, SUM(CASE WHEN B.CHANNEL_CODE = 'STORE' THEN B.TOTAL_AMOUNT ELSE 0 END) AS STORE_AMT, SUM(CASE WHEN B.CHANNEL_CODE = 'B2B' THEN B.TOTAL_AMOUNT ELSE 0 END) AS B2B_AMT, SUM(CASE WHEN DL.DELIVERED_AT > DL.PROMISED_AT THEN 1 ELSE 0 END) AS LATE_CNT, COUNT(DISTINCT B.ORDER_ID) AS ORD_CNT FROM ORD_BASE B LEFT JOIN ITEM_AGG I ON I.ORDER_ID = B.ORDER_ID LEFT JOIN DLV_LAST DL ON DL.ORDER_ID = B.ORDER_ID WHERE B.CUST_RGN = 'DAEGU' GROUP BY B.CUSTOMER_ID ), R_INCHEON AS ( /* 인천 권역 */ SELECT B.CUSTOMER_ID, SUM(CASE WHEN B.CUST_GRD = 'VVIP' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS VVIP_AMT, SUM(CASE WHEN B.CUST_GRD = 'VIP' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS VIP_AMT, SUM(CASE WHEN B.CUST_GRD = 'GOLD' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS GOLD_AMT, SUM(CASE WHEN B.CUST_GRD = 'SILVER' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS SILVER_AMT, SUM(CASE WHEN B.CUST_GRD = 'BASIC' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS BASIC_AMT, SUM(CASE WHEN B.CHANNEL_CODE = 'WEB' THEN B.TOTAL_AMOUNT ELSE 0 END) AS WEB_AMT, SUM(CASE WHEN B.CHANNEL_CODE = 'APP' THEN B.TOTAL_AMOUNT ELSE 0 END) AS APP_AMT, SUM(CASE WHEN B.CHANNEL_CODE = 'CALL' THEN B.TOTAL_AMOUNT ELSE 0 END) AS CALL_AMT, SUM(CASE WHEN B.CHANNEL_CODE = 'STORE' THEN B.TOTAL_AMOUNT ELSE 0 END) AS STORE_AMT, SUM(CASE WHEN B.CHANNEL_CODE = 'B2B' THEN B.TOTAL_AMOUNT ELSE 0 END) AS B2B_AMT, SUM(CASE WHEN DL.DELIVERED_AT > DL.PROMISED_AT THEN 1 ELSE 0 END) AS LATE_CNT, COUNT(DISTINCT B.ORDER_ID) AS ORD_CNT FROM ORD_BASE B LEFT JOIN ITEM_AGG I ON I.ORDER_ID = B.ORDER_ID LEFT JOIN DLV_LAST DL ON DL.ORDER_ID = B.ORDER_ID WHERE B.CUST_RGN = 'INCHEON' GROUP BY B.CUSTOMER_ID ), R_GWANGJU AS ( /* 광주 권역 */ SELECT B.CUSTOMER_ID, SUM(CASE WHEN B.CUST_GRD = 'VVIP' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS VVIP_AMT, SUM(CASE WHEN B.CUST_GRD = 'VIP' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS VIP_AMT, SUM(CASE WHEN B.CUST_GRD = 'GOLD' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS GOLD_AMT, SUM(CASE WHEN B.CUST_GRD = 'SILVER' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS SILVER_AMT, SUM(CASE WHEN B.CUST_GRD = 'BASIC' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS BASIC_AMT, SUM(CASE WHEN B.CHANNEL_CODE = 'WEB' THEN B.TOTAL_AMOUNT ELSE 0 END) AS WEB_AMT, SUM(CASE WHEN B.CHANNEL_CODE = 'APP' THEN B.TOTAL_AMOUNT ELSE 0 END) AS APP_AMT, SUM(CASE WHEN B.CHANNEL_CODE = 'CALL' THEN B.TOTAL_AMOUNT ELSE 0 END) AS CALL_AMT, SUM(CASE WHEN B.CHANNEL_CODE = 'STORE' THEN B.TOTAL_AMOUNT ELSE 0 END) AS STORE_AMT, SUM(CASE WHEN B.CHANNEL_CODE = 'B2B' THEN B.TOTAL_AMOUNT ELSE 0 END) AS B2B_AMT, SUM(CASE WHEN DL.DELIVERED_AT > DL.PROMISED_AT THEN 1 ELSE 0 END) AS LATE_CNT, COUNT(DISTINCT B.ORDER_ID) AS ORD_CNT FROM ORD_BASE B LEFT JOIN ITEM_AGG I ON I.ORDER_ID = B.ORDER_ID LEFT JOIN DLV_LAST DL ON DL.ORDER_ID = B.ORDER_ID WHERE B.CUST_RGN = 'GWANGJU' GROUP BY B.CUSTOMER_ID ), R_DAEJEON AS ( /* 대전 권역 */ SELECT B.CUSTOMER_ID, SUM(CASE WHEN B.CUST_GRD = 'VVIP' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS VVIP_AMT, SUM(CASE WHEN B.CUST_GRD = 'VIP' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS VIP_AMT, SUM(CASE WHEN B.CUST_GRD = 'GOLD' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS GOLD_AMT, SUM(CASE WHEN B.CUST_GRD = 'SILVER' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS SILVER_AMT, SUM(CASE WHEN B.CUST_GRD = 'BASIC' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS BASIC_AMT, SUM(CASE WHEN B.CHANNEL_CODE = 'WEB' THEN B.TOTAL_AMOUNT ELSE 0 END) AS WEB_AMT, SUM(CASE WHEN B.CHANNEL_CODE = 'APP' THEN B.TOTAL_AMOUNT ELSE 0 END) AS APP_AMT, SUM(CASE WHEN B.CHANNEL_CODE = 'CALL' THEN B.TOTAL_AMOUNT ELSE 0 END) AS CALL_AMT, SUM(CASE WHEN B.CHANNEL_CODE = 'STORE' THEN B.TOTAL_AMOUNT ELSE 0 END) AS STORE_AMT, SUM(CASE WHEN B.CHANNEL_CODE = 'B2B' THEN B.TOTAL_AMOUNT ELSE 0 END) AS B2B_AMT, SUM(CASE WHEN DL.DELIVERED_AT > DL.PROMISED_AT THEN 1 ELSE 0 END) AS LATE_CNT, COUNT(DISTINCT B.ORDER_ID) AS ORD_CNT FROM ORD_BASE B LEFT JOIN ITEM_AGG I ON I.ORDER_ID = B.ORDER_ID LEFT JOIN DLV_LAST DL ON DL.ORDER_ID = B.ORDER_ID WHERE B.CUST_RGN = 'DAEJEON' GROUP BY B.CUSTOMER_ID ), R_ULSAN AS ( /* 울산 권역 */ SELECT B.CUSTOMER_ID, SUM(CASE WHEN B.CUST_GRD = 'VVIP' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS VVIP_AMT, SUM(CASE WHEN B.CUST_GRD = 'VIP' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS VIP_AMT, SUM(CASE WHEN B.CUST_GRD = 'GOLD' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS GOLD_AMT, SUM(CASE WHEN B.CUST_GRD = 'SILVER' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS SILVER_AMT, SUM(CASE WHEN B.CUST_GRD = 'BASIC' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS BASIC_AMT, SUM(CASE WHEN B.CHANNEL_CODE = 'WEB' THEN B.TOTAL_AMOUNT ELSE 0 END) AS WEB_AMT, SUM(CASE WHEN B.CHANNEL_CODE = 'APP' THEN B.TOTAL_AMOUNT ELSE 0 END) AS APP_AMT, SUM(CASE WHEN B.CHANNEL_CODE = 'CALL' THEN B.TOTAL_AMOUNT ELSE 0 END) AS CALL_AMT, SUM(CASE WHEN B.CHANNEL_CODE = 'STORE' THEN B.TOTAL_AMOUNT ELSE 0 END) AS STORE_AMT, SUM(CASE WHEN B.CHANNEL_CODE = 'B2B' THEN B.TOTAL_AMOUNT ELSE 0 END) AS B2B_AMT, SUM(CASE WHEN DL.DELIVERED_AT > DL.PROMISED_AT THEN 1 ELSE 0 END) AS LATE_CNT, COUNT(DISTINCT B.ORDER_ID) AS ORD_CNT FROM ORD_BASE B LEFT JOIN ITEM_AGG I ON I.ORDER_ID = B.ORDER_ID LEFT JOIN DLV_LAST DL ON DL.ORDER_ID = B.ORDER_ID WHERE B.CUST_RGN = 'ULSAN' GROUP BY B.CUSTOMER_ID ), R_SEJONG AS ( /* 세종 권역 */ SELECT B.CUSTOMER_ID, SUM(CASE WHEN B.CUST_GRD = 'VVIP' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS VVIP_AMT, SUM(CASE WHEN B.CUST_GRD = 'VIP' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS VIP_AMT, SUM(CASE WHEN B.CUST_GRD = 'GOLD' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS GOLD_AMT, SUM(CASE WHEN B.CUST_GRD = 'SILVER' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS SILVER_AMT, SUM(CASE WHEN B.CUST_GRD = 'BASIC' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS BASIC_AMT, SUM(CASE WHEN B.CHANNEL_CODE = 'WEB' THEN B.TOTAL_AMOUNT ELSE 0 END) AS WEB_AMT, SUM(CASE WHEN B.CHANNEL_CODE = 'APP' THEN B.TOTAL_AMOUNT ELSE 0 END) AS APP_AMT, SUM(CASE WHEN B.CHANNEL_CODE = 'CALL' THEN B.TOTAL_AMOUNT ELSE 0 END) AS CALL_AMT, SUM(CASE WHEN B.CHANNEL_CODE = 'STORE' THEN B.TOTAL_AMOUNT ELSE 0 END) AS STORE_AMT, SUM(CASE WHEN B.CHANNEL_CODE = 'B2B' THEN B.TOTAL_AMOUNT ELSE 0 END) AS B2B_AMT, SUM(CASE WHEN DL.DELIVERED_AT > DL.PROMISED_AT THEN 1 ELSE 0 END) AS LATE_CNT, COUNT(DISTINCT B.ORDER_ID) AS ORD_CNT FROM ORD_BASE B LEFT JOIN ITEM_AGG I ON I.ORDER_ID = B.ORDER_ID LEFT JOIN DLV_LAST DL ON DL.ORDER_ID = B.ORDER_ID WHERE B.CUST_RGN = 'SEJONG' GROUP BY B.CUSTOMER_ID ), R_GYEONGGI AS ( /* 경기 권역 */ SELECT B.CUSTOMER_ID, SUM(CASE WHEN B.CUST_GRD = 'VVIP' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS VVIP_AMT, SUM(CASE WHEN B.CUST_GRD = 'VIP' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS VIP_AMT, SUM(CASE WHEN B.CUST_GRD = 'GOLD' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS GOLD_AMT, SUM(CASE WHEN B.CUST_GRD = 'SILVER' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS SILVER_AMT, SUM(CASE WHEN B.CUST_GRD = 'BASIC' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS BASIC_AMT, SUM(CASE WHEN B.CHANNEL_CODE = 'WEB' THEN B.TOTAL_AMOUNT ELSE 0 END) AS WEB_AMT, SUM(CASE WHEN B.CHANNEL_CODE = 'APP' THEN B.TOTAL_AMOUNT ELSE 0 END) AS APP_AMT, SUM(CASE WHEN B.CHANNEL_CODE = 'CALL' THEN B.TOTAL_AMOUNT ELSE 0 END) AS CALL_AMT, SUM(CASE WHEN B.CHANNEL_CODE = 'STORE' THEN B.TOTAL_AMOUNT ELSE 0 END) AS STORE_AMT, SUM(CASE WHEN B.CHANNEL_CODE = 'B2B' THEN B.TOTAL_AMOUNT ELSE 0 END) AS B2B_AMT, SUM(CASE WHEN DL.DELIVERED_AT > DL.PROMISED_AT THEN 1 ELSE 0 END) AS LATE_CNT, COUNT(DISTINCT B.ORDER_ID) AS ORD_CNT FROM ORD_BASE B LEFT JOIN ITEM_AGG I ON I.ORDER_ID = B.ORDER_ID LEFT JOIN DLV_LAST DL ON DL.ORDER_ID = B.ORDER_ID WHERE B.CUST_RGN = 'GYEONGGI' GROUP BY B.CUSTOMER_ID ), R_GANGWON AS ( /* 강원 권역 */ SELECT B.CUSTOMER_ID, SUM(CASE WHEN B.CUST_GRD = 'VVIP' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS VVIP_AMT, SUM(CASE WHEN B.CUST_GRD = 'VIP' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS VIP_AMT, SUM(CASE WHEN B.CUST_GRD = 'GOLD' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS GOLD_AMT, SUM(CASE WHEN B.CUST_GRD = 'SILVER' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS SILVER_AMT, SUM(CASE WHEN B.CUST_GRD = 'BASIC' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS BASIC_AMT, SUM(CASE WHEN B.CHANNEL_CODE = 'WEB' THEN B.TOTAL_AMOUNT ELSE 0 END) AS WEB_AMT, SUM(CASE WHEN B.CHANNEL_CODE = 'APP' THEN B.TOTAL_AMOUNT ELSE 0 END) AS APP_AMT, SUM(CASE WHEN B.CHANNEL_CODE = 'CALL' THEN B.TOTAL_AMOUNT ELSE 0 END) AS CALL_AMT, SUM(CASE WHEN B.CHANNEL_CODE = 'STORE' THEN B.TOTAL_AMOUNT ELSE 0 END) AS STORE_AMT, SUM(CASE WHEN B.CHANNEL_CODE = 'B2B' THEN B.TOTAL_AMOUNT ELSE 0 END) AS B2B_AMT, SUM(CASE WHEN DL.DELIVERED_AT > DL.PROMISED_AT THEN 1 ELSE 0 END) AS LATE_CNT, COUNT(DISTINCT B.ORDER_ID) AS ORD_CNT FROM ORD_BASE B LEFT JOIN ITEM_AGG I ON I.ORDER_ID = B.ORDER_ID LEFT JOIN DLV_LAST DL ON DL.ORDER_ID = B.ORDER_ID WHERE B.CUST_RGN = 'GANGWON' GROUP BY B.CUSTOMER_ID ), R_CHUNGBUK AS ( /* 충북 권역 */ SELECT B.CUSTOMER_ID, SUM(CASE WHEN B.CUST_GRD = 'VVIP' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS VVIP_AMT, SUM(CASE WHEN B.CUST_GRD = 'VIP' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS VIP_AMT, SUM(CASE WHEN B.CUST_GRD = 'GOLD' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS GOLD_AMT, SUM(CASE WHEN B.CUST_GRD = 'SILVER' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS SILVER_AMT, SUM(CASE WHEN B.CUST_GRD = 'BASIC' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS BASIC_AMT, SUM(CASE WHEN B.CHANNEL_CODE = 'WEB' THEN B.TOTAL_AMOUNT ELSE 0 END) AS WEB_AMT, SUM(CASE WHEN B.CHANNEL_CODE = 'APP' THEN B.TOTAL_AMOUNT ELSE 0 END) AS APP_AMT, SUM(CASE WHEN B.CHANNEL_CODE = 'CALL' THEN B.TOTAL_AMOUNT ELSE 0 END) AS CALL_AMT, SUM(CASE WHEN B.CHANNEL_CODE = 'STORE' THEN B.TOTAL_AMOUNT ELSE 0 END) AS STORE_AMT, SUM(CASE WHEN B.CHANNEL_CODE = 'B2B' THEN B.TOTAL_AMOUNT ELSE 0 END) AS B2B_AMT, SUM(CASE WHEN DL.DELIVERED_AT > DL.PROMISED_AT THEN 1 ELSE 0 END) AS LATE_CNT, COUNT(DISTINCT B.ORDER_ID) AS ORD_CNT FROM ORD_BASE B LEFT JOIN ITEM_AGG I ON I.ORDER_ID = B.ORDER_ID LEFT JOIN DLV_LAST DL ON DL.ORDER_ID = B.ORDER_ID WHERE B.CUST_RGN = 'CHUNGBUK' GROUP BY B.CUSTOMER_ID ), R_CHUNGNAM AS ( /* 충남 권역 */ SELECT B.CUSTOMER_ID, SUM(CASE WHEN B.CUST_GRD = 'VVIP' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS VVIP_AMT, SUM(CASE WHEN B.CUST_GRD = 'VIP' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS VIP_AMT, SUM(CASE WHEN B.CUST_GRD = 'GOLD' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS GOLD_AMT, SUM(CASE WHEN B.CUST_GRD = 'SILVER' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS SILVER_AMT, SUM(CASE WHEN B.CUST_GRD = 'BASIC' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS BASIC_AMT, SUM(CASE WHEN B.CHANNEL_CODE = 'WEB' THEN B.TOTAL_AMOUNT ELSE 0 END) AS WEB_AMT, SUM(CASE WHEN B.CHANNEL_CODE = 'APP' THEN B.TOTAL_AMOUNT ELSE 0 END) AS APP_AMT, SUM(CASE WHEN B.CHANNEL_CODE = 'CALL' THEN B.TOTAL_AMOUNT ELSE 0 END) AS CALL_AMT, SUM(CASE WHEN B.CHANNEL_CODE = 'STORE' THEN B.TOTAL_AMOUNT ELSE 0 END) AS STORE_AMT, SUM(CASE WHEN B.CHANNEL_CODE = 'B2B' THEN B.TOTAL_AMOUNT ELSE 0 END) AS B2B_AMT, SUM(CASE WHEN DL.DELIVERED_AT > DL.PROMISED_AT THEN 1 ELSE 0 END) AS LATE_CNT, COUNT(DISTINCT B.ORDER_