UM(CASE WHEN B.CHANNEL_CODE = 'WEB' THEN NVL(I.ITEM_AMT, 0) - NVL(CP.DC_SUM, 0) ELSE 0 END) AS WEB_NET, SUM(CASE WHEN B.CHANNEL_CODE = 'WEB' THEN 1 ELSE 0 END) AS WEB_CNT, SUM(CASE WHEN B.CHANNEL_CODE = 'WEB' AND RT.RTN_CNT > 0 THEN RT.RTN_SUM ELSE 0 END) AS WEB_RTN, SUM(CASE WHEN B.CHANNEL_CODE = 'WEB' THEN NVL(I.ITEM_QTY, 0) ELSE 0 END) AS WEB_QTY, SUM(CASE WHEN B.CHANNEL_CODE = 'WEB' THEN NVL(CP.DC_SUM, 0) ELSE 0 END) AS WEB_DC, SUM(CASE WHEN B.CHANNEL_CODE = 'WEB' THEN NVL(PY.PAY_SUM, 0) ELSE 0 END) AS WEB_PAY, SUM(CASE WHEN B.CHANNEL_CODE = 'WEB' AND B.TOTAL_AMOUNT >= 1000000 THEN 1 ELSE 0 END) AS WEB_BIG_CNT, /* 앱 */ SUM(CASE WHEN B.CHANNEL_CODE = 'APP' THEN NVL(I.ITEM_AMT, 0) - NVL(CP.DC_SUM, 0) ELSE 0 END) AS APP_NET, SUM(CASE WHEN B.CHANNEL_CODE = 'APP' THEN 1 ELSE 0 END) AS APP_CNT, SUM(CASE WHEN B.CHANNEL_CODE = 'APP' AND RT.RTN_CNT > 0 THEN RT.RTN_SUM ELSE 0 END) AS APP_RTN, SUM(CASE WHEN B.CHANNEL_CODE = 'APP' THEN NVL(I.ITEM_QTY, 0) ELSE 0 END) AS APP_QTY, SUM(CASE WHEN B.CHANNEL_CODE = 'APP' THEN NVL(CP.DC_SUM, 0) ELSE 0 END) AS APP_DC, SUM(CASE WHEN B.CHANNEL_CODE = 'APP' THEN NVL(PY.PAY_SUM, 0) ELSE 0 END) AS APP_PAY, SUM(CASE WHEN B.CHANNEL_CODE = 'APP' AND B.TOTAL_AMOUNT >= 1000000 THEN 1 ELSE 0 END) AS APP_BIG_CNT, /* 콜센터 */ SUM(CASE WHEN B.CHANNEL_CODE = 'CALL' THEN NVL(I.ITEM_AMT, 0) - NVL(CP.DC_SUM, 0) ELSE 0 END) AS CALL_NET, SUM(CASE WHEN B.CHANNEL_CODE = 'CALL' THEN 1 ELSE 0 END) AS CALL_CNT, SUM(CASE WHEN B.CHANNEL_CODE = 'CALL' AND RT.RTN_CNT > 0 THEN RT.RTN_SUM ELSE 0 END) AS CALL_RTN, SUM(CASE WHEN B.CHANNEL_CODE = 'CALL' THEN NVL(I.ITEM_QTY, 0) ELSE 0 END) AS CALL_QTY, SUM(CASE WHEN B.CHANNEL_CODE = 'CALL' THEN NVL(CP.DC_SUM, 0) ELSE 0 END) AS CALL_DC, SUM(CASE WHEN B.CHANNEL_CODE = 'CALL' THEN NVL(PY.PAY_SUM, 0) ELSE 0 END) AS CALL_PAY, SUM(CASE WHEN B.CHANNEL_CODE = 'CALL' AND B.TOTAL_AMOUNT >= 1000000 THEN 1 ELSE 0 END) AS CALL_BIG_CNT, /* 매장 */ SUM(CASE WHEN B.CHANNEL_CODE = 'STORE' THEN NVL(I.ITEM_AMT, 0) - NVL(CP.DC_SUM, 0) ELSE 0 END) AS STORE_NET, SUM(CASE WHEN B.CHANNEL_CODE = 'STORE' THEN 1 ELSE 0 END) AS STORE_CNT, SUM(CASE WHEN B.CHANNEL_CODE = 'STORE' AND RT.RTN_CNT > 0 THEN RT.RTN_SUM ELSE 0 END) AS STORE_RTN, SUM(CASE WHEN B.CHANNEL_CODE = 'STORE' THEN NVL(I.ITEM_QTY, 0) ELSE 0 END) AS STORE_QTY, SUM(CASE WHEN B.CHANNEL_CODE = 'STORE' THEN NVL(CP.DC_SUM, 0) ELSE 0 END) AS STORE_DC, SUM(CASE WHEN B.CHANNEL_CODE = 'STORE' THEN NVL(PY.PAY_SUM, 0) ELSE 0 END) AS STORE_PAY, SUM(CASE WHEN B.CHANNEL_CODE = 'STORE' AND B.TOTAL_AMOUNT >= 1000000 THEN 1 ELSE 0 END) AS STORE_BIG_CNT, /* 기업 */ SUM(CASE WHEN B.CHANNEL_CODE = 'B2B' THEN NVL(I.ITEM_AMT, 0) - NVL(CP.DC_SUM, 0) ELSE 0 END) AS B2B_NET, SUM(CASE WHEN B.CHANNEL_CODE = 'B2B' THEN 1 ELSE 0 END) AS B2B_CNT, SUM(CASE WHEN B.CHANNEL_CODE = 'B2B' AND RT.RTN_CNT > 0 THEN RT.RTN_SUM ELSE 0 END) AS B2B_RTN, SUM(CASE WHEN B.CHANNEL_CODE = 'B2B' THEN NVL(I.ITEM_QTY, 0) ELSE 0 END) AS B2B_QTY, SUM(CASE WHEN B.CHANNEL_CODE = 'B2B' THEN NVL(CP.DC_SUM, 0) ELSE 0 END) AS B2B_DC, SUM(CASE WHEN B.CHANNEL_CODE = 'B2B' THEN NVL(PY.PAY_SUM, 0) ELSE 0 END) AS B2B_PAY, SUM(CASE WHEN B.CHANNEL_CODE = 'B2B' AND B.TOTAL_AMOUNT >= 1000000 THEN 1 ELSE 0 END) AS B2B_BIG_CNT, SUM(NVL(PY.PAY_SUM, 0)) AS PAY_TOTAL, MAX(B.ORDERED_AT) AS LAST_ORD_DT FROM ORD_BASE B LEFT JOIN ITEM_AGG I ON I.ORDER_ID = B.ORDER_ID LEFT JOIN CPN_AGG CP ON CP.ORDER_ID = B.ORDER_ID LEFT JOIN RTN_AGG RT ON RT.ORDER_ID = B.ORDER_ID LEFT JOIN PAY_AGG PY ON PY.ORDER_ID = B.ORDER_ID WHERE B.ORD_YM = #year# || '11' GROUP BY B.CUSTOMER_ID ), M12 AS ( /* 12월 채널별 실적 */ SELECT B.CUSTOMER_ID, /* 웹 */ SUM(CASE WHEN B.CHANNEL_CODE = 'WEB' THEN NVL(I.ITEM_AMT, 0) - NVL(CP.DC_SUM, 0) ELSE 0 END) AS WEB_NET, SUM(CASE WHEN B.CHANNEL_CODE = 'WEB' THEN 1 ELSE 0 END) AS WEB_CNT, SUM(CASE WHEN B.CHANNEL_CODE = 'WEB' AND RT.RTN_CNT > 0 THEN RT.RTN_SUM ELSE 0 END) AS WEB_RTN, SUM(CASE WHEN B.CHANNEL_CODE = 'WEB' THEN NVL(I.ITEM_QTY, 0) ELSE 0 END) AS WEB_QTY, SUM(CASE WHEN B.CHANNEL_CODE = 'WEB' THEN NVL(CP.DC_SUM, 0) ELSE 0 END) AS WEB_DC, SUM(CASE WHEN B.CHANNEL_CODE = 'WEB' THEN NVL(PY.PAY_SUM, 0) ELSE 0 END) AS WEB_PAY, SUM(CASE WHEN B.CHANNEL_CODE = 'WEB' AND B.TOTAL_AMOUNT >= 1000000 THEN 1 ELSE 0 END) AS WEB_BIG_CNT, /* 앱 */ SUM(CASE WHEN B.CHANNEL_CODE = 'APP' THEN NVL(I.ITEM_AMT, 0) - NVL(CP.DC_SUM, 0) ELSE 0 END) AS APP_NET, SUM(CASE WHEN B.CHANNEL_CODE = 'APP' THEN 1 ELSE 0 END) AS APP_CNT, SUM(CASE WHEN B.CHANNEL_CODE = 'APP' AND RT.RTN_CNT > 0 THEN RT.RTN_SUM ELSE 0 END) AS APP_RTN, SUM(CASE WHEN B.CHANNEL_CODE = 'APP' THEN NVL(I.ITEM_QTY, 0) ELSE 0 END) AS APP_QTY, SUM(CASE WHEN B.CHANNEL_CODE = 'APP' THEN NVL(CP.DC_SUM, 0) ELSE 0 END) AS APP_DC, SUM(CASE WHEN B.CHANNEL_CODE = 'APP' THEN NVL(PY.PAY_SUM, 0) ELSE 0 END) AS APP_PAY, SUM(CASE WHEN B.CHANNEL_CODE = 'APP' AND B.TOTAL_AMOUNT >= 1000000 THEN 1 ELSE 0 END) AS APP_BIG_CNT, /* 콜센터 */ SUM(CASE WHEN B.CHANNEL_CODE = 'CALL' THEN NVL(I.ITEM_AMT, 0) - NVL(CP.DC_SUM, 0) ELSE 0 END) AS CALL_NET, SUM(CASE WHEN B.CHANNEL_CODE = 'CALL' THEN 1 ELSE 0 END) AS CALL_CNT, SUM(CASE WHEN B.CHANNEL_CODE = 'CALL' AND RT.RTN_CNT > 0 THEN RT.RTN_SUM ELSE 0 END) AS CALL_RTN, SUM(CASE WHEN B.CHANNEL_CODE = 'CALL' THEN NVL(I.ITEM_QTY, 0) ELSE 0 END) AS CALL_QTY, SUM(CASE WHEN B.CHANNEL_CODE = 'CALL' THEN NVL(CP.DC_SUM, 0) ELSE 0 END) AS CALL_DC, SUM(CASE WHEN B.CHANNEL_CODE = 'CALL' THEN NVL(PY.PAY_SUM, 0) ELSE 0 END) AS CALL_PAY, SUM(CASE WHEN B.CHANNEL_CODE = 'CALL' AND B.TOTAL_AMOUNT >= 1000000 THEN 1 ELSE 0 END) AS CALL_BIG_CNT, /* 매장 */ SUM(CASE WHEN B.CHANNEL_CODE = 'STORE' THEN NVL(I.ITEM_AMT, 0) - NVL(CP.DC_SUM, 0) ELSE 0 END) AS STORE_NET, SUM(CASE WHEN B.CHANNEL_CODE = 'STORE' THEN 1 ELSE 0 END) AS STORE_CNT, SUM(CASE WHEN B.CHANNEL_CODE = 'STORE' AND RT.RTN_CNT > 0 THEN RT.RTN_SUM ELSE 0 END) AS STORE_RTN, SUM(CASE WHEN B.CHANNEL_CODE = 'STORE' THEN NVL(I.ITEM_QTY, 0) ELSE 0 END) AS STORE_QTY, SUM(CASE WHEN B.CHANNEL_CODE = 'STORE' THEN NVL(CP.DC_SUM, 0) ELSE 0 END) AS STORE_DC, SUM(CASE WHEN B.CHANNEL_CODE = 'STORE' THEN NVL(PY.PAY_SUM, 0) ELSE 0 END) AS STORE_PAY, SUM(CASE WHEN B.CHANNEL_CODE = 'STORE' AND B.TOTAL_AMOUNT >= 1000000 THEN 1 ELSE 0 END) AS STORE_BIG_CNT, /* 기업 */ SUM(CASE WHEN B.CHANNEL_CODE = 'B2B' THEN NVL(I.ITEM_AMT, 0) - NVL(CP.DC_SUM, 0) ELSE 0 END) AS B2B_NET, SUM(CASE WHEN B.CHANNEL_CODE = 'B2B' THEN 1 ELSE 0 END) AS B2B_CNT, SUM(CASE WHEN B.CHANNEL_CODE = 'B2B' AND RT.RTN_CNT > 0 THEN RT.RTN_SUM ELSE 0 END) AS B2B_RTN, SUM(CASE WHEN B.CHANNEL_CODE = 'B2B' THEN NVL(I.ITEM_QTY, 0) ELSE 0 END) AS B2B_QTY, SUM(CASE WHEN B.CHANNEL_CODE = 'B2B' THEN NVL(CP.DC_SUM, 0) ELSE 0 END) AS B2B_DC, SUM(CASE WHEN B.CHANNEL_CODE = 'B2B' THEN NVL(PY.PAY_SUM, 0) ELSE 0 END) AS B2B_PAY, SUM(CASE WHEN B.CHANNEL_CODE = 'B2B' AND B.TOTAL_AMOUNT >= 1000000 THEN 1 ELSE 0 END) AS B2B_BIG_CNT, SUM(NVL(PY.PAY_SUM, 0)) AS PAY_TOTAL, MAX(B.ORDERED_AT) AS LAST_ORD_DT FROM ORD_BASE B LEFT JOIN ITEM_AGG I ON I.ORDER_ID = B.ORDER_ID LEFT JOIN CPN_AGG CP ON CP.ORDER_ID = B.ORDER_ID LEFT JOIN RTN_AGG RT ON RT.ORDER_ID = B.ORDER_ID LEFT JOIN PAY_AGG PY ON PY.ORDER_ID = B.ORDER_ID WHERE B.ORD_YM = #year# || '12' GROUP BY B.CUSTOMER_ID ) SELECT B.CUSTOMER_ID AS CUST_KEY, MAX(B.CUST_NAME) AS CUST_NAME, MAX((SELECT G.CODE_NAME FROM COMMON_CODE G WHERE G.GROUP_CODE = 'CUST_GRD' AND G.CODE = B.CUST_GRD)) AS CUST_GRD_NM, MAX(ED.EMPLOYEE_NAME || ' (' || ED.DEPARTMENT_NAME || ')') AS SALES_REP, COUNT(DISTINCT B.ORDER_ID) AS ORD_CNT, SUM(B.TOTAL_AMOUNT) AS ORD_AMT, SUM(NVL(I.ITEM_AMT, 0)) AS ITEM_AMT, SUM(NVL(I.ITEM_QTY, 0)) AS ITEM_QTY, SUM(NVL(PY.PAY_SUM, 0)) AS PAY_AMT, SUM(NVL(PY.CARD_SUM, 0)) AS CARD_AMT, SUM(NVL(PY.BANK_SUM, 0)) AS BANK_AMT, SUM(NVL(PY.POINT_SUM, 0)) AS POINT_AMT, SUM(NVL(CP.DC_SUM, 0)) AS DC_AMT, SUM(NVL(RT.RTN_SUM, 0)) AS RTN_AMT, SUM(CASE WHEN DL.DELIVERY_STATUS = 'DONE' THEN 1 ELSE 0 END) AS DLV_DONE_CNT, SUM(CASE WHEN DL.DELIVERED_AT > DL.PROMISED_AT THEN 1 ELSE 0 END) AS DLV_LATE_CNT, SUM(DECODE(DL.CARRIER_CODE, 'CJ', 1, 0)) AS DLV_CJ_CNT, SUM(CASE WHEN B.CUST_GRD = 'VVI