 NVL(R_GYEONGNAM.VIP_AMT, 0)) AS R_GYEONGNAM_TOP_AMT, SUM(NVL(R_JEJU.VVIP_AMT, 0) + NVL(R_JEJU.VIP_AMT, 0)) AS R_JEJU_TOP_AMT, SUM(NVL(R_SEOUL.LATE_CNT, 0)) AS R_SEOUL_LATE, SUM(NVL(R_BUSAN.LATE_CNT, 0)) AS R_BUSAN_LATE, SUM(NVL(R_DAEGU.LATE_CNT, 0)) AS R_DAEGU_LATE, SUM(NVL(R_INCHEON.LATE_CNT, 0)) AS R_INCHEON_LATE, SUM(NVL(R_GWANGJU.LATE_CNT, 0)) AS R_GWANGJU_LATE, SUM(NVL(R_DAEJEON.LATE_CNT, 0)) AS R_DAEJEON_LATE, SUM(NVL(R_ULSAN.LATE_CNT, 0)) AS R_ULSAN_LATE, SUM(NVL(R_SEJONG.LATE_CNT, 0)) AS R_SEJONG_LATE, SUM(NVL(R_GYEONGGI.LATE_CNT, 0)) AS R_GYEONGGI_LATE, SUM(NVL(R_GANGWON.LATE_CNT, 0)) AS R_GANGWON_LATE, SUM(NVL(R_CHUNGBUK.LATE_CNT, 0)) AS R_CHUNGBUK_LATE, SUM(NVL(R_CHUNGNAM.LATE_CNT, 0)) AS R_CHUNGNAM_LATE, SUM(NVL(R_JEONBUK.LATE_CNT, 0)) AS R_JEONBUK_LATE, SUM(NVL(R_JEONNAM.LATE_CNT, 0)) AS R_JEONNAM_LATE, SUM(NVL(R_GYEONGBUK.LATE_CNT, 0)) AS R_GYEONGBUK_LATE, SUM(NVL(R_GYEONGNAM.LATE_CNT, 0)) AS R_GYEONGNAM_LATE, SUM(NVL(R_JEJU.LATE_CNT, 0)) AS R_JEJU_LATE, SUM(NVL(CS.CTG_AMT, 0)) AS CTG_AMT, MAX(CS.TOP_CTG_NM) AS TOP_CTG_NM, MAX(B.ORDERED_AT) AS LAST_ORD_DT FROM ORD_BASE B LEFT JOIN ITEM_AGG I ON I.ORDER_ID = B.ORDER_ID LEFT JOIN PAY_AGG PY ON PY.ORDER_ID = B.ORDER_ID LEFT JOIN CPN_AGG CP ON CP.ORDER_ID = B.ORDER_ID LEFT JOIN RTN_AGG RT ON RT.ORDER_ID = B.ORDER_ID LEFT JOIN DLV_LAST DL ON DL.ORDER_ID = B.ORDER_ID LEFT JOIN EMP_DEPT ED ON ED.EMPLOYEE_ID = B.SALES_REP_ID LEFT JOIN CTG_SALES CS ON CS.ORDER_ID = B.ORDER_ID LEFT JOIN R_SEOUL ON R_SEOUL.CUSTOMER_ID = B.CUSTOMER_ID LEFT JOIN R_BUSAN ON R_BUSAN.CUSTOMER_ID = B.CUSTOMER_ID LEFT JOIN R_DAEGU ON R_DAEGU.CUSTOMER_ID = B.CUSTOMER_ID LEFT JOIN R_INCHEON ON R_INCHEON.CUSTOMER_ID = B.CUSTOMER_ID LEFT JOIN R_GWANGJU ON R_GWANGJU.CUSTOMER_ID = B.CUSTOMER_ID LEFT JOIN R_DAEJEON ON R_DAEJEON.CUSTOMER_ID = B.CUSTOMER_ID LEFT JOIN R_ULSAN ON R_ULSAN.CUSTOMER_ID = B.CUSTOMER_ID LEFT JOIN R_SEJONG ON R_SEJONG.CUSTOMER_ID = B.CUSTOMER_ID LEFT JOIN R_GYEONGGI ON R_GYEONGGI.CUSTOMER_ID = B.CUSTOMER_ID LEFT JOIN R_GANGWON ON R_GANGWON.CUSTOMER_ID = B.CUSTOMER_ID LEFT JOIN R_CHUNGBUK ON R_CHUNGBUK.CUSTOMER_ID = B.CUSTOMER_ID LEFT JOIN R_CHUNGNAM ON R_CHUNGNAM.CUSTOMER_ID = B.CUSTOMER_ID LEFT JOIN R_JEONBUK ON R_JEONBUK.CUSTOMER_ID = B.CUSTOMER_ID LEFT JOIN R_JEONNAM ON R_JEONNAM.CUSTOMER_ID = B.CUSTOMER_ID LEFT JOIN R_GYEONGBUK ON R_GYEONGBUK.CUSTOMER_ID = B.CUSTOMER_ID LEFT JOIN R_GYEONGNAM ON R_GYEONGNAM.CUSTOMER_ID = B.CUSTOMER_ID LEFT JOIN R_JEJU ON R_JEJU.CUSTOMER_ID = B.CUSTOMER_ID LEFT JOIN M01 ON M01.CUSTOMER_ID = B.CUSTOMER_ID LEFT JOIN M02 ON M02.CUSTOMER_ID = B.CUSTOMER_ID LEFT JOIN M03 ON M03.CUSTOMER_ID = B.CUSTOMER_ID LEFT JOIN M04 ON M04.CUSTOMER_ID = B.CUSTOMER_ID LEFT JOIN M05 ON M05.CUSTOMER_ID = B.CUSTOMER_ID LEFT JOIN M06 ON M06.CUSTOMER_ID = B.CUSTOMER_ID LEFT JOIN M07 ON M07.CUSTOMER_ID = B.CUSTOMER_ID LEFT JOIN M08 ON M08.CUSTOMER_ID = B.CUSTOMER_ID LEFT JOIN M09 ON M09.CUSTOMER_ID = B.CUSTOMER_ID LEFT JOIN M10 ON M10.CUSTOMER_ID = B.CUSTOMER_ID LEFT JOIN M11 ON M11.CUSTOMER_ID = B.CUSTOMER_ID LEFT JOIN M12 ON M12.CUSTOMER_ID = B.CUSTOMER_ID WHERE 1 = 1
